r _ { 2 } = \frac { n _ { 2 } ^ { ' } L _ { 2 } } { n _ { 2 } + n _ { 2 } ^ { ' } } = \frac { L _ { 2 } } { n + 1 } = \frac { - \, 100 } { 2. \, 5 } \mathrm { m m = - 40 m m }
