&=2A+2B\left[\cos\left(\frac{2\pi\Delta}{\bar\lambda}\right)\cos\left(\frac{\Delta\lambda}{\bar\lambda^2}\pi\Delta\right)\right]\\
&=2A\left[1+\frac BA\cos\left(\frac{\Delta\lambda}{\bar\lambda^2}\pi\Delta\right)\cos\delta\right]
\end{aligned}

